#include <windows.h>
#include <iostream>

HHOOK g_hook = nullptr;

// Low-level keyboard callback.
// This does NOT log keys. It only checks for Ctrl+Alt+K.
LRESULT CALLBACK LowLevelKeyboardProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (nCode == HC_ACTION)
    {
        KBDLLHOOKSTRUCT* p = reinterpret_cast<KBDLLHOOKSTRUCT*>(lParam);

        if (wParam == WM_KEYDOWN || wParam == WM_SYSKEYDOWN)
        {
            const bool ctrl = (GetAsyncKeyState(VK_CONTROL) & 0x8000) != 0;
            const bool alt  = (GetAsyncKeyState(VK_MENU)    & 0x8000) != 0;

            if (ctrl && alt && p->vkCode == 'K')
            {
                // Hotkey detected. Signal shutdown instead of logging.
                PostQuitMessage(0);
            }
        }
    }

    return CallNextHookEx(g_hook, nCode, wParam, lParam);
}

int main()
{
    g_hook = SetWindowsHookExW(
        WH_KEYBOARD_LL,
        LowLevelKeyboardProc,
        GetModuleHandleW(nullptr),
        0
    );

    if (!g_hook)
    {
        std::cerr << "SetWindowsHookExW failed: " << GetLastError() << "\n";
        return 1;
    }

    std::cout << "Hotkey listener active. Press Ctrl+Alt+K to exit.\n";

    MSG msg;
